<script>
let nextBlock={{ $page->blocks->count() }};
function renumber(){document.querySelectorAll('[data-block]').forEach((el,i)=>{el.querySelector('strong').textContent='ბლოკი #'+(i+1);el.querySelectorAll('[name]').forEach(input=>input.name=input.name.replace(/blocks\[\d+\]/,'blocks['+i+']'));});nextBlock=document.querySelectorAll('[data-block]').length;}
function addBlock(){const i=nextBlock++;const el=document.createElement('div');el.className='block-editor';el.setAttribute('data-block','');el.innerHTML='<div class="section-heading"><strong>ბლოკი #'+(i+1)+'</strong><button type="button" class="btn btn-small">წაშლა</button></div><div class="two"><div><label>ტიპი</label><select name="blocks['+i+'][type]"><option value="heading">სათაური</option><option value="text">ტექსტი</option><option value="image">სურათის ბმული</option><option value="button">ღილაკი</option><option value="contact">კონტაქტი</option><option value="catalog">კატალოგი</option><option value="hours">სამუშაო საათები</option></select></div><div><label>ბლოკის სათაური</label><input name="blocks['+i+'][title]"></div></div><label>ტექსტი / სურათის URL / საათები</label><textarea name="blocks['+i+'][text]" rows="3"></textarea><label>ღილაკის ან სურათის URL</label><input name="blocks['+i+'][url]" type="url"><label><input type="checkbox" name="blocks['+i+'][is_visible]" value="1" checked> ხილული იყოს</label>';el.querySelector('button').onclick=()=>{el.remove();renumber()};document.getElementById('blocks').appendChild(el);}
</script></body></html>